/* @autogenerated */
package net.civeira.phylax.common.infrastructure.consistency;

import java.time.Clock;
import java.time.Duration;
import java.time.OffsetDateTime;
import java.time.ZoneOffset;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

import org.eclipse.microprofile.config.inject.ConfigProperty;

import io.quarkus.cache.Cache;
import io.quarkus.cache.CacheName;
import io.quarkus.cache.runtime.noop.NoOpCache;
import io.quarkus.scheduler.Scheduled;
import jakarta.enterprise.context.ApplicationScoped;
import jakarta.inject.Inject;
import jakarta.transaction.Status;
import jakarta.transaction.Synchronization;
import jakarta.transaction.TransactionSynchronizationRegistry;
import lombok.extern.slf4j.Slf4j;

/**
 * Keeps track of the recent writes of each entity, so the infrastructure can read from the primary
 * database (and skip caching) while the query side may still be behind.
 *
 * <p>
 * A write opens a window that lasts {@code phylax.consistency.pending-writes.window}. When the
 * write happens inside a transaction, the window is opened again when the transaction commits, so
 * it covers the replication lag counted from the moment the change can reach the replica.
 * </p>
 *
 * <p>
 * The marks live on the {@code pending-writes} Quarkus cache, so the backend is chosen by
 * configuration. When the Quarkus cache is disabled, the marks are kept on a local map (valid only
 * for a single pod) that is purged periodically.
 * </p>
 */
@Slf4j
@ApplicationScoped
public class PendingWritesRegistry {

  /**
   * Value stored by the readers when there is no mark: it is always expired.
   */
  private static final OffsetDateTime NO_MARK =
      OffsetDateTime.of(1970, 1, 1, 0, 0, 0, 0, ZoneOffset.UTC);

  /**
   * Attempts to store a mark when a reader stores {@link #NO_MARK} between the invalidation and the
   * store.
   */
  private static final int MARK_ATTEMPTS = 5;

  /**
   * Prefix of the transaction resource used to register the commit renewal only once per entity.
   */
  private static final String RESOURCE_PREFIX = PendingWritesRegistry.class.getName() + ":";

  /**
   * Marks on the Quarkus cache, or null when the Quarkus cache is disabled.
   */
  private final Cache marks;

  /**
   * Marks used when the Quarkus cache is disabled.
   */
  private final Map<String, OffsetDateTime> localMarks = new ConcurrentHashMap<>();

  private final TransactionSynchronizationRegistry transactions;

  private final Duration window;

  private final Clock clock;

  @Inject
  public PendingWritesRegistry(@CacheName("pending-writes") final Cache cache,
      final TransactionSynchronizationRegistry transactions,
      @ConfigProperty(name = "phylax.consistency.pending-writes.window",
          defaultValue = "60S") final Duration window) {
    this(cache, transactions, window, Clock.systemUTC());
  }

  PendingWritesRegistry(final Cache cache, final TransactionSynchronizationRegistry transactions,
      final Duration window, final Clock clock) {
    if (cache instanceof NoOpCache) {
      log.info("Quarkus cache is disabled: pending writes are kept on this pod only");
      this.marks = null;
    } else {
      this.marks = cache;
    }
    this.transactions = transactions;
    this.window = window;
    this.clock = clock;
  }

  /**
   * Registers a write of the entity: opens the pending writes window now and, if there is an active
   * transaction, opens it again after the commit.
   *
   * @param entity the name of the written entity
   */
  public void mark(final String entity) {
    renew(entity);
    if (Status.STATUS_ACTIVE == transactions.getTransactionStatus()
        && null == transactions.getResource(RESOURCE_PREFIX + entity)) {
      transactions.putResource(RESOURCE_PREFIX + entity, Boolean.TRUE);
      transactions.registerInterposedSynchronization(new Synchronization() {
        @Override
        public void beforeCompletion() {
          // Nothing to do before the commit
        }

        @Override
        public void afterCompletion(final int status) {
          if (Status.STATUS_COMMITTED == status) {
            renew(entity);
          }
        }
      });
    }
  }

  /**
   * Tells whether the entity has been written inside the pending writes window.
   *
   * @param entity the name of the entity
   * @return true while reads must go to the primary database and must not be cached
   */
  public boolean isPending(final String entity) {
    OffsetDateTime deadline = null == marks ? localMarks.get(entity)
        : marks.<String, OffsetDateTime>get(entity, _ -> NO_MARK).await().indefinitely();
    return null != deadline && deadline.isAfter(OffsetDateTime.now(clock));
  }

  /**
   * Removes the expired marks of the local map. The Quarkus cache purges its own entries with its
   * expire-after-write.
   */
  @Scheduled(every = "${phylax.consistency.pending-writes.purge:5m}",
      concurrentExecution = Scheduled.ConcurrentExecution.SKIP)
  void purge() {
    OffsetDateTime now = OffsetDateTime.now(clock);
    localMarks.values().removeIf(deadline -> !deadline.isAfter(now));
  }

  private void renew(final String entity) {
    OffsetDateTime deadline = OffsetDateTime.now(clock).plus(window);
    if (null == marks) {
      localMarks.merge(entity, deadline, (prev, next) -> next.isAfter(prev) ? next : prev);
    } else {
      store(entity, deadline);
    }
    log.trace("Pending writes window for {} until {}", entity, deadline);
  }

  /**
   * The generic cache has no put: the mark is stored invalidating the key and loading it again. A
   * reader may store {@link #NO_MARK} in between, so the store is checked and retried. Any other
   * value found was stored by another write after the invalidation, so it is a valid mark too.
   */
  private void store(final String entity, final OffsetDateTime deadline) {
    for (int attempt = 0; attempt < MARK_ATTEMPTS; attempt++) {
      marks.invalidate(entity).await().indefinitely();
      OffsetDateTime stored =
          marks.<String, OffsetDateTime>get(entity, _ -> deadline).await().indefinitely();
      if (!NO_MARK.equals(stored)) {
        return;
      }
    }
    log.warn("Unable to store the pending writes mark of {} after {} attempts", entity,
        MARK_ATTEMPTS);
  }
}
